<?php
$root=dirname(__DIR__);$errors=[];$warn=[];$routes=file_get_contents($root.'/routes/web.php');
preg_match_all('/use\\s+App\\\\Http\\\\Controllers(?:\\\\Admin)?\\\\\\{([^}]+)\\};/',$routes,$um);$imports=[];foreach($um[1] as $g)foreach(explode(',',$g) as $n)$imports[trim($n)]=true;
preg_match_all("/\\[([A-Za-z_][A-Za-z0-9_]*Controller)::class\\s*,\\s*'([^']+)'\\]/",$routes,$rm,PREG_SET_ORDER);
foreach($rm as $x){$c=$x[1];$method=$x[2];if(!isset($imports[$c]))$errors[]="Route controller is not imported: $c";$file=null;foreach(["$root/app/Http/Controllers/$c.php","$root/app/Http/Controllers/Admin/$c.php"] as $p)if(is_file($p)){$file=$p;break;}if(!$file){$errors[]="Missing controller: $c";continue;}$body=file_get_contents($file);if(!preg_match('/function\\s+'.preg_quote($method,'/').'\\s*\\(/',$body))$errors[]="Missing controller method: $c::$method";}
preg_match_all("/->name\\('([^']+)'\\)/",$routes,$nm);$routeNames=array_fill_keys($nm[1],true);
$views=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator("$root/resources/views"));foreach($it as $file){if(!$file->isFile()||!str_ends_with($file->getFilename(),'.blade.php'))continue;$body=file_get_contents($file->getPathname());preg_match_all("/route\\('([^']+)'/",$body,$m);foreach($m[1] as $n)if(!isset($routeNames[$n]))$errors[]="Blade uses missing route [$n]: ".str_replace($root.'/','',$file->getPathname());}
$php=[];foreach(["$root/app/Http/Controllers","$root/app/Services"] as $dir){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir));foreach($it as $file)if($file->isFile()&&$file->getExtension()==='php')$php[]=$file->getPathname();}
foreach($php as $path){$body=file_get_contents($path);preg_match_all("/view\\('([^']+)'/",$body,$vm);foreach($vm[1] as $v){$vf="$root/resources/views/".str_replace('.','/',$v).".blade.php";if(!is_file($vf))$errors[]="Missing view [$v] referenced by ".str_replace($root.'/','',$path);}}
$errors=array_values(array_unique($errors));echo "Route actions: ".count($rm)."\nNamed routes: ".count($routeNames)."\nBlade files checked: ".iterator_count(new RecursiveIteratorIterator(new RecursiveDirectoryIterator("$root/resources/views")))."\nPHP files checked: ".count($php)."\n";if($errors){echo "\nERRORS (".count($errors)."):\n".implode("\n",$errors)."\n";exit(1);}echo "\nOK: routes, controller imports/methods, Blade route names and referenced views are consistent.\n";